/*
 * A129703  Number of different walks generated by n steps that can only go in
 *          {east, southeast, southwest} directions on the 300-degree wedge in
 *          a 60-degree equilateral triangular lattice.
 * https://oeis.org/A129703
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, walk
 * Formula:   Recurrence * (3+n)*a(n+2) = (3+3n)*a(n) + (6+2n)*a(n+1) - 6 -
 *            4n, * with a(0)=1, a(1)=3, a(2)=6
 * Range:     u8 n <= 4, u16 n <= 9, u32 n <= 18, u64 n <= 26, u128 n <= 26,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>

seq_t a(idx_t n)
{
    /* Handle the initial values directly. */
    if (n == 0) return (seq_t)1;
    if (n == 1) return (seq_t)3;
    if (n == 2) return (seq_t)6;

    /* prev2 = a(i), prev1 = a(i+1). Start with i = 1: a(1), a(2). */
    seq_t prev2 = (seq_t)3;   /* a(1) */
    seq_t prev1 = (seq_t)6;   /* a(2) */

    for (idx_t i = 1; ; ++i)
    {
        /* Compute a(i+2) from the recurrence. */
        seq_t part1 = ((seq_t)(3 + 3*i)) * prev2;
        seq_t part2 = ((seq_t)(6 + 2*i)) * prev1;
        seq_t numerator = part1 + part2;
        numerator -= (seq_t)(6 + 4*i);
        seq_t denominator = (seq_t)(3 + i);
        seq_t cur = numerator / denominator;   /* exact division */

        /* If we've reached the desired index, return the value. */
        if (i + 2 == n) return cur;

        /* Shift for the next iteration. */
        prev2 = prev1;
        prev1 = cur;
    }
}
